 871→  protected async handleAttachment(sessionId: string, content: OutgoingMessage): Promise<void> {
 872→    if (!content.attachment) return;
 873→    const { attachment } = content;
 874→    const { thread, isAssistant } = this.getSessionContext(sessionId);
 875→    await this.draftManager.finalize(
 876→      sessionId,
 877→      thread,
 878→      isAssistant,
 879→    );
 880→
 881→    // Discord free tier limit: 25MB
 882→    if (isAttachmentTooLarge(attachment.size)) {
 883→      log.warn(
 884→        {
 885→          sessionId,
 886→          fileName: attachment.fileName,
 887→          size: attachment.size,
 888→        },
 889→        "[discord-media] File too large (>25MB)",
 890→      );
 891→      try {
 892→        await this.sendQueue.enqueue(
 893→          () =>
 894→            thread.send({
 895→              content: `⚠️ File too large to send (${Math.round(attachment.size / 1024 / 1024)}MB): ${attachment.fileName}`,
 896→            }),
 897→          { type: "other" },
 898→        );
 899→      } catch {
 900→        /* best effort */
 901→      }
 902→      return;
 903→    }
 904→
 905→    try {
 906→      await this.sendQueue.enqueue(
 907→        () =>
 908→          thread.send({
 909→            files: [
 910→              { attachment: attachment.filePath, name: attachment.fileName },
 911→            ],
 912→          }),
 913→        { type: "other" },
 914→      );
 915→
 916→      // Strip [TTS]...[/TTS] block from the text message after audio is sent.
 917→      // This fires after sendQueue completes, so the draft message already exists.
 918→      // stripPattern is best-effort and handles missing/finalized drafts gracefully.
 919→      if (attachment.type === "audio") {
 920→        const draft = this.draftManager.getDraft(sessionId);
 921→        if (draft) {
 922→          draft.stripPattern(/\[TTS\][\s\S]*?\[\/TTS\]/g).catch(() => {});
 923→        }
 924→      }
 925→    } catch (err) {
 926→      log.error(
 927→        { err, sessionId, fileName: attachment.fileName },
 928→        "[discord-media] Failed to send attachment",
 929→      );
 930→    }
 931→  }
