  91→    this.client = new Client({
  92→      intents: [
  93→        GatewayIntentBits.Guilds,
  94→        GatewayIntentBits.GuildMessages,
  95→        GatewayIntentBits.MessageContent,
  96→      ],
  97→    });
  98→
  99→    this.sendQueue = new SendQueue({ minInterval: 1000 });
