 74→export class LifecycleManager {
 75→  readonly serviceRegistry: ServiceRegistry
 76→  readonly middlewareChain: MiddlewareChain
 77→  readonly errorTracker: ErrorTracker
 78→
 79→  private eventBus: LifecycleManagerOpts['eventBus']
 80→  private storagePath: string
 81→  private sessions: unknown
 82→  private config: unknown
 83→  private core: unknown
 84→  private log: Logger | undefined
 85→  private settingsManager: SettingsManager | undefined
 86→  private pluginRegistry: PluginRegistry | undefined
 87→
 88→  private contexts = new Map<string, ReturnType<typeof createPluginContext>>()
 89→  private loadOrder: OpenACPPlugin[] = []
 90→  private _loaded = new Set<string>()
 91→  private _failed = new Set<string>()
 92→
 93→  get loadedPlugins(): string[] {
 94→    return [...this._loaded]
 95→  }
 96→
 97→  get failedPlugins(): string[] {
 98→    return [...this._failed]
 99→  }
100→
101→  constructor(opts?: LifecycleManagerOpts) {
102→    this.serviceRegistry = opts?.serviceRegistry ?? new ServiceRegistry()
103→    this.middlewareChain = opts?.middlewareChain ?? new MiddlewareChain()
104→    this.errorTracker = opts?.errorTracker ?? new ErrorTracker()
105→    this.eventBus = opts?.eventBus ?? {
106→      on() {},
107→      off() {},
108→      emit() {},
109→    }
110→    this.storagePath = opts?.storagePath ?? '/tmp/openacp-plugins'
111→    this.sessions = opts?.sessions ?? {}
112→    this.config = opts?.config ?? {}
113→    this.core = opts?.core
114→    this.log = opts?.log
115→    this.settingsManager = opts?.settingsManager
116→    this.pluginRegistry = opts?.pluginRegistry
117→  }
118→
119→  private getPluginLogger(pluginName: string): Logger {
120→    if (this.log && typeof (this.log as any).child === 'function') {
121→      return (this.log as any).child({ plugin: pluginName })
122→    }
123→    return this.log ?? { trace() {}, debug() {}, info() {}, warn() {}, error() {}, fatal() {}, child() { return this } } as Logger
124→  }
125→
126→  async boot(plugins: OpenACPPlugin[]): Promise<void> {
127→    // Resolve load order via topological sort.
128→    // resolveLoadOrder will skip plugins whose dependencies are missing entirely
129→    // (not present in the input list). But we also need to handle runtime setup failures.
130→    let sorted: OpenACPPlugin[]
131→    try {
132→      sorted = resolveLoadOrder(plugins)
133→    } catch (err) {
134→      // Circular dependency or other fatal error in resolution
135→      // Mark all as failed
136→      for (const p of plugins) {
137→        this._failed.add(p.name)
138→      }
139→      return
140→    }
141→
142→    // Append to existing loadOrder (don't overwrite — hot-reload boots single plugins)
143→    for (const p of sorted) {
144→      if (!this.loadOrder.some(existing => existing.name === p.name)) {
145→        this.loadOrder.push(p)
146→      } else {
147→        // Replace in-place (hot-reload case: plugin was unloaded then re-booted)
148→        const idx = this.loadOrder.findIndex(existing => existing.name === p.name)
149→        this.loadOrder[idx] = p
150→      }
151→    }
152→
153→    for (const plugin of sorted) {
154→      // Check if any required dependency failed at runtime
155→      if (plugin.pluginDependencies) {
156→        const depFailed = Object.keys(plugin.pluginDependencies).some(
157→          (dep) => this._failed.has(dep),
158→        )
159→        if (depFailed) {
160→          this._failed.add(plugin.name)
161→          continue
162→        }
163→      }
164→
165→      // Check if disabled in registry
166→      const registryEntry = this.pluginRegistry?.get(plugin.name)
167→      if (registryEntry && registryEntry.enabled === false) {
168→        this.eventBus?.emit('plugin:disabled', { name: plugin.name })
169→        continue
170→      }
171→
172→      // Check version mismatch → migrate
173→      if (registryEntry && plugin.migrate && registryEntry.version !== plugin.version && this.settingsManager) {
174→        try {
175→          const oldSettings = await this.settingsManager.loadSettings(plugin.name)
176→          const pluginLog = this.getPluginLogger(plugin.name)
177→          const migrateCtx: MigrateContext = {
178→            pluginName: plugin.name,
179→            settings: this.settingsManager.createAPI(plugin.name),
180→            log: pluginLog,
181→          }
182→          const newSettings = await plugin.migrate(migrateCtx, oldSettings, registryEntry.version)
183→          if (newSettings && typeof newSettings === 'object') {
184→            await migrateCtx.settings.setAll(newSettings as Record<string, unknown>)
185→          }
186→          this.pluginRegistry!.updateVersion(plugin.name, plugin.version)
187→          await this.pluginRegistry!.save()
188→        } catch (err) {
189→          this.getPluginLogger(plugin.name).warn(`Migration failed, continuing with old settings: ${err}`)
190→        }
191→      }
192→
193→      // Resolve config: prefer settings.json, fallback to legacy
194→      let pluginConfig: Record<string, unknown>
195→      if (this.settingsManager) {
196→        pluginConfig = await this.settingsManager.loadSettings(plugin.name)
197→        if (Object.keys(pluginConfig).length === 0) {
198→          pluginConfig = resolvePluginConfig(plugin.name, this.config)
199→        }
200→      } else {
201→        pluginConfig = resolvePluginConfig(plugin.name, this.config)
202→      }
203→
204→      // Create context for this plugin
205→      const ctx = createPluginContext({
206→        pluginName: plugin.name,
207→        pluginConfig,
208→        permissions: plugin.permissions ?? [],
209→        serviceRegistry: this.serviceRegistry,
210→        middlewareChain: this.middlewareChain,
211→        errorTracker: this.errorTracker,
212→        eventBus: this.eventBus!,
213→        storagePath: `${this.storagePath}/${plugin.name}`,
214→        sessions: this.sessions,
215→        config: this.config,
216→        core: this.core,
217→        log: this.log,
218→      })
219→
220→      try {
221→        await withTimeout(plugin.setup(ctx), SETUP_TIMEOUT_MS, `${plugin.name}.setup()`)
222→        this.contexts.set(plugin.name, ctx)
223→        this._loaded.add(plugin.name)
224→        this.eventBus?.emit('plugin:loaded', { name: plugin.name, version: plugin.version })
225→      } catch (err) {
226→        this._failed.add(plugin.name)
227→        ctx.cleanup()
228→        this.getPluginLogger(plugin.name).error(`setup() failed: ${err}`)
229→        this.eventBus?.emit('plugin:failed', { name: plugin.name, error: String(err) })
230→      }
231→    }
232→  }
233→
234→  async unloadPlugin(name: string): Promise<void> {
235→    if (!this._loaded.has(name)) return
236→
237→    const plugin = this.loadOrder.find(p => p.name === name)
238→
239→    if (plugin?.teardown) {
240→      try {
241→        await withTimeout(plugin.teardown(), TEARDOWN_TIMEOUT_MS, `${name}.teardown()`)
242→      } catch {
243→        // Swallow teardown errors
244→      }
245→    }
246→
247→    const ctx = this.contexts.get(name)
248→    if (ctx) {
249→      ctx.cleanup()
250→      this.contexts.delete(name)
251→    }
252→
253→    this._loaded.delete(name)
254→    this._failed.delete(name)
255→    this.loadOrder = this.loadOrder.filter(p => p.name !== name)
256→
257→    this.eventBus?.emit('plugin:unloaded', { name })
258→  }
259→
260→  async shutdown(): Promise<void> {
261→    // Teardown in reverse load order
262→    const reversed = [...this.loadOrder].reverse()
263→
264→    for (const plugin of reversed) {
265→      if (!this._loaded.has(plugin.name)) continue
266→
267→      if (plugin.teardown) {
268→        try {
269→          await withTimeout(plugin.teardown(), TEARDOWN_TIMEOUT_MS, `${plugin.name}.teardown()`)
270→        } catch {
271→          // Swallow teardown errors — graceful shutdown
272→        }
273→      }
274→
275→      // Clean up the context
276→      const ctx = this.contexts.get(plugin.name)
277→      if (ctx) {
278→        ctx.cleanup()
279→        this.contexts.delete(plugin.name)
280→      }
281→
282→      this.eventBus?.emit('plugin:unloaded', { name: plugin.name })
283→    }
284→
285→    this._loaded.clear()
286→    this.loadOrder = []
287→  }
288→}
