 17→const ALL_CHECKS: DoctorCheck[] = [
 18→  configCheck,
 19→  agentsCheck,
 20→  telegramCheck,
 21→  discordCheck,
 22→  storageCheck,
 23→  workspaceCheck,
 24→  pluginsCheck,
 25→  daemonCheck,
 26→  tunnelCheck,
 27→];
