 29→const CHECK_TIMEOUT_MS = 10_000;
 30→
 31→export class DoctorEngine {
 32→  private dryRun: boolean;
 33→
 34→  constructor(options?: { dryRun?: boolean }) {
 35→    this.dryRun = options?.dryRun ?? false;
 36→  }
 37→
 38→  async runAll(): Promise<DoctorReport> {
 39→    const ctx = await this.buildContext();
 40→    const checks = [...ALL_CHECKS].sort((a, b) => a.order - b.order);
 41→
 42→    const categories: CategoryResult[] = [];
 43→    const pendingFixes: PendingFix[] = [];
 44→    const summary = { passed: 0, warnings: 0, failed: 0, fixed: 0 };
 45→
 46→    for (const check of checks) {
 47→      let results: CheckResult[];
 48→      try {
 49→        results = await Promise.race([
 50→          check.run(ctx),
 51→          new Promise<CheckResult[]>((_, reject) =>
 52→            setTimeout(() => reject(new Error("timeout")), CHECK_TIMEOUT_MS),
 53→          ),
 54→        ]);
 55→      } catch {
 56→        results = [{ status: "fail", message: `${check.name} check timed out` }];
 57→      }
 58→
 59→      for (const result of results) {
 60→        if (result.fixable && result.fix) {
 61→          if (result.fixRisk === "safe" && !this.dryRun) {
 62→            try {
 63→              const fixResult = await result.fix();
 64→              if (fixResult.success) {
 65→                result.message += ` → Fixed (${fixResult.message})`;
 66→                result.status = "warn";
 67→                delete result.fix;
 68→                summary.fixed++;
 69→              }
 70→            } catch {
 71→              // Fix failed, leave as-is
 72→            }
 73→          } else if (result.fixRisk === "risky") {
 74→            pendingFixes.push({
 75→              category: check.name,
 76→              message: result.message,
 77→              fix: result.fix,
 78→            });
 79→          }
 80→        }
 81→
 82→        if (result.status === "pass") summary.passed++;
 83→        else if (result.status === "warn") summary.warnings++;
 84→        else if (result.status === "fail") summary.failed++;
 85→      }
 86→
 87→      categories.push({ name: check.name, results });
 88→    }
 89→
 90→    return { categories, summary, pendingFixes };
 91→  }
 92→
 93→  private async buildContext(): Promise<DoctorContext> {
 94→    const dataDir = path.join(os.homedir(), ".openacp");
 95→    const configPath = process.env.OPENACP_CONFIG_PATH || path.join(dataDir, "config.json");
 96→
 97→    let config = null;
 98→    let rawConfig: unknown = null;
 99→
100→    try {
101→      const content = fs.readFileSync(configPath, "utf-8");
102→      rawConfig = JSON.parse(content);
103→      const cm = new ConfigManager();
104→      await cm.load();
105→      config = cm.get();
106→    } catch {
107→      // Config may not exist or may be invalid — checks will handle this
108→    }
109→
110→    const logsDir = config
111→      ? expandHome(config.logging.logDir)
112→      : path.join(dataDir, "logs");
113→
114→    return {
115→      config,
116→      rawConfig,
117→      configPath,
118→      dataDir,
119→      sessionsPath: path.join(dataDir, "sessions.json"),
120→      pidPath: path.join(dataDir, "openacp.pid"),
121→      portFilePath: path.join(dataDir, "api.port"),
122→      pluginsDir: path.join(dataDir, "plugins"),
123→      logsDir,
124→    };
125→  }
126→}
