 22→// --- Variadic wrapper for backward compatibility ---
 23→function wrapVariadic(logger: pino.Logger) {
 24→  return {
 25→    info: (...args: unknown[]) => {
 26→      if (args.length === 0) return
 27→      if (typeof args[0] === 'object' && args[0] !== null && !(args[0] instanceof Error)) {
 28→        logger.info(args[0] as object, args.slice(1).join(' '))
 29→      } else {
 30→        logger.info(args.map(String).join(' '))
 31→      }
 32→    },
 33→    warn: (...args: unknown[]) => {
 34→      if (args.length === 0) return
 35→      if (typeof args[0] === 'object' && args[0] !== null && !(args[0] instanceof Error)) {
 36→        logger.warn(args[0] as object, args.slice(1).join(' '))
 37→      } else {
 38→        logger.warn(args.map(String).join(' '))
 39→      }
 40→    },
 41→    error: (...args: unknown[]) => {
 42→      if (args.length === 0) return
 43→      if (typeof args[0] === 'object' && args[0] !== null && !(args[0] instanceof Error)) {
 44→        logger.error(args[0] as object, args.slice(1).join(' '))
 45→      } else {
 46→        logger.error(args.map(String).join(' '))
 47→      }
 48→    },
 49→    debug: (...args: unknown[]) => {
 50→      if (args.length === 0) return
 51→      if (typeof args[0] === 'object' && args[0] !== null && !(args[0] instanceof Error)) {
 52→        logger.debug(args[0] as object, args.slice(1).join(' '))
 53→      } else {
 54→        logger.debug(args.map(String).join(' '))
 55→      }
 56→    },
 57→    fatal: (...args: unknown[]) => {
 58→      if (args.length === 0) return
 59→      if (typeof args[0] === 'object' && args[0] !== null && !(args[0] instanceof Error)) {
 60→        logger.fatal(args[0] as object, args.slice(1).join(' '))
 61→      } else {
 62→        logger.fatal(args.map(String).join(' '))
 63→      }
 64→    },
 65→    child: (bindings: pino.Bindings) => logger.child(bindings),
 66→  }
 67→}
