 71→// --- Mute/unmute (suppress pino output during interactive prompts) ---
 72→
 73→let muteCount = 0
 74→let savedLevel = 'info'
 75→
 76→export function muteLogger(): void {
 77→  if (muteCount === 0) {
 78→    savedLevel = rootLogger.level
 79→    rootLogger.level = 'silent'
 80→  }
 81→  muteCount++
 82→}
 83→
 84→export function unmuteLogger(): void {
 85→  muteCount--
 86→  if (muteCount <= 0) {
 87→    muteCount = 0
 88→    rootLogger.level = savedLevel
 89→  }
 90→}
