 92→// --- Public API ---
 93→
 94→export function initLogger(config: LoggingConfig): Logger {
 95→  if (initialized) return rootLogger
 96→
 97→  const resolvedLogDir = expandHome(config.logDir)
 98→  logDir = resolvedLogDir
 99→
100→  try {
101→    fs.mkdirSync(resolvedLogDir, { recursive: true })
102→    fs.mkdirSync(path.join(resolvedLogDir, 'sessions'), { recursive: true })
103→  } catch (err) {
104→    console.error(`[WARN] Failed to create log directory ${resolvedLogDir}, falling back to console-only:`, err)
105→    return rootLogger
106→  }
107→
108→  const transports = pino.transport({
109→    targets: [
110→      {
111→        target: 'pino-pretty',
112→        options: {
113→          colorize: true,
114→          translateTime: 'HH:mm:ss',
115→          ignore: 'pid,hostname',
116→          singleLine: true,
117→        },
118→        level: config.level,
119→      },
120→      {
121→        target: 'pino-roll',
122→        options: {
123→          file: path.join(resolvedLogDir, 'openacp.log'),
124→          size: config.maxFileSize,
125→          limit: { count: config.maxFiles },
126→        },
127→        level: config.level,
128→      },
129→    ],
130→  })
131→
132→  currentTransport = transports
133→  rootLogger = pino({ level: config.level }, transports)
134→  initialized = true
135→
136→  // Update the default log wrapper to use the new root logger
137→  Object.assign(log, wrapVariadic(rootLogger))
138→
139→  return rootLogger
140→}
141→
142→/** Change log level at runtime. Pino transport targets respect parent level changes automatically. */
143→export function setLogLevel(level: string): void {
144→  rootLogger.level = level
145→}
146→
147→export function createChildLogger(context: { module: string; [key: string]: unknown }): Logger {
148→  // Return a proxy that always delegates to the current rootLogger.
149→  // This ensures child loggers created at module-level (before initLogger)
150→  // pick up the initialized logger with pino-pretty transport.
151→  return new Proxy({} as Logger, {
152→    get(_target, prop, receiver) {
153→      const child = rootLogger.child(context)
154→      const value = Reflect.get(child, prop, receiver)
155→      return typeof value === 'function' ? value.bind(child) : value
156→    },
157→  })
158→}
159→
160→export function createSessionLogger(sessionId: string, parentLogger: Logger): Logger {
161→  const sessionLogDir = logDir ? path.join(logDir, 'sessions') : undefined
162→  if (!sessionLogDir) {
163→    return parentLogger.child({ sessionId })
164→  }
165→
166→  try {
167→    const sessionLogPath = path.join(sessionLogDir, `${sessionId}.log`)
168→    const dest = pino.destination(sessionLogPath)
169→    const sessionFileLogger = pino({ level: parentLogger.level }, dest).child({ sessionId })
170→
171→    // Create a logger that writes to both parent (combined) and session file
172→    const combinedChild = parentLogger.child({ sessionId })
173→    const originalInfo = combinedChild.info.bind(combinedChild)
174→    const originalWarn = combinedChild.warn.bind(combinedChild)
175→    const originalError = combinedChild.error.bind(combinedChild)
176→    const originalDebug = combinedChild.debug.bind(combinedChild)
177→    const originalFatal = combinedChild.fatal.bind(combinedChild)
178→
179→    // Proxy log methods to write to both destinations
180→    combinedChild.info = ((objOrMsg: any, ...rest: any[]) => {
181→      sessionFileLogger.info(objOrMsg, ...rest)
182→      return originalInfo(objOrMsg, ...rest)
183→    }) as any
184→    combinedChild.warn = ((objOrMsg: any, ...rest: any[]) => {
185→      sessionFileLogger.warn(objOrMsg, ...rest)
186→      return originalWarn(objOrMsg, ...rest)
187→    }) as any
188→    combinedChild.error = ((objOrMsg: any, ...rest: any[]) => {
189→      sessionFileLogger.error(objOrMsg, ...rest)
190→      return originalError(objOrMsg, ...rest)
191→    }) as any
192→    combinedChild.debug = ((objOrMsg: any, ...rest: any[]) => {
193→      sessionFileLogger.debug(objOrMsg, ...rest)
194→      return originalDebug(objOrMsg, ...rest)
195→    }) as any
196→    combinedChild.fatal = ((objOrMsg: any, ...rest: any[]) => {
197→      sessionFileLogger.fatal(objOrMsg, ...rest)
198→      return originalFatal(objOrMsg, ...rest)
199→    }) as any
200→
201→    // Store dest for cleanup
202→    ;(combinedChild as any).__sessionDest = dest
203→
204→    return combinedChild
205→  } catch (err) {
206→    // Graceful degradation: session file failed, just use combined log
207→    parentLogger.warn({ sessionId, err }, 'Failed to create session log file, using combined log only')
208→    return parentLogger.child({ sessionId })
209→  }
210→}
211→
212→export async function shutdownLogger(): Promise<void> {
213→  if (!initialized) return
214→
215→  const transport = currentTransport
216→
217→  // Reset state immediately so re-init is possible
218→  rootLogger = pino({ level: 'debug' })
219→  Object.assign(log, wrapVariadic(rootLogger))
220→  currentTransport = undefined
221→  logDir = undefined
222→  initialized = false
223→
224→  if (transport) {
225→    await new Promise<void>((resolve) => {
226→      const timeout = setTimeout(resolve, 3000)
227→      transport.on('close', () => {
228→        clearTimeout(timeout)
229→        resolve()
230→      })
231→      transport.end()
232→    })
233→  }
234→}
235→
236→export async function cleanupOldSessionLogs(retentionDays: number): Promise<void> {
237→  if (!logDir) return
238→
239→  const sessionsDir = path.join(logDir, 'sessions')
240→  try {
241→    const files = await fs.promises.readdir(sessionsDir)
242→    const cutoff = Date.now() - retentionDays * 24 * 60 * 60 * 1000
243→
244→    for (const file of files) {
245→      try {
246→        const filePath = path.join(sessionsDir, file)
247→        const stat = await fs.promises.stat(filePath)
248→        if (stat.mtimeMs < cutoff) {
249→          await fs.promises.unlink(filePath)
250→          rootLogger.debug({ file }, 'Deleted old session log')
251→        }
252→      } catch (err) {
253→        rootLogger.warn({ file, err }, 'Failed to delete old session log')
254→      }
255→    }
256→  } catch {
257→    // Sessions directory doesn't exist — no-op
258→  }
259→}
