 54→/**
 55→ * BaseRenderer — plain text defaults. Extend for platform-specific rendering.
 56→ */
 57→export class BaseRenderer implements IRenderer {
 58→  renderText(content: OutgoingMessage): RenderedMessage {
 59→    return { body: content.text, format: 'plain' }
 60→  }
 61→
 62→  renderToolCall(content: OutgoingMessage, verbosity: DisplayVerbosity): RenderedMessage {
 63→    const meta = (content.metadata ?? {}) as Partial<ToolCallMeta>
 64→    const name = meta.name ?? content.text ?? 'Tool'
 65→    const icon = resolveToolIcon(meta)
 66→    const label = verbosity === 'low'
 67→      ? formatToolTitle(name, meta.rawInput, meta.displayTitle as string | undefined)
 68→      : formatToolSummary(name, meta.rawInput, meta.displaySummary as string | undefined)
 69→    return { body: `${icon} ${label}`, format: 'plain' }
 70→  }
 71→
 72→  renderToolUpdate(content: OutgoingMessage, verbosity: DisplayVerbosity): RenderedMessage {
 73→    const meta = (content.metadata ?? {}) as Partial<ToolUpdateMeta>
 74→    const name = meta.name ?? content.text ?? 'Tool'
 75→    const icon = resolveToolIcon(meta)
 76→    const label = verbosity === 'low'
 77→      ? formatToolTitle(name, meta.rawInput, meta.displayTitle as string | undefined)
 78→      : formatToolSummary(name, meta.rawInput, meta.displaySummary as string | undefined)
 79→    return { body: `${icon} ${label}`, format: 'plain' }
 80→  }
 81→
 82→  renderPlan(content: OutgoingMessage, verbosity: DisplayVerbosity): RenderedMessage {
 83→    const entries = (content.metadata as { entries?: Array<{ content: string; status: string }> })?.entries ?? []
 84→    const done = entries.filter(e => e.status === 'completed').length
 85→    if (verbosity === 'medium' || verbosity === 'low') {
 86→      return { body: `📋 Plan: ${done}/${entries.length} steps completed`, format: 'plain' }
 87→    }
 88→    const lines = entries.map((e, i) => {
 89→      const icon = e.status === 'completed' ? '✅' : e.status === 'in_progress' ? '🔄' : '⬜'
 90→      return `${icon} ${i + 1}. ${e.content}`
 91→    })
 92→    return { body: `📋 Plan\n${lines.join('\n')}`, format: 'plain' }
 93→  }
 94→
 95→  renderUsage(content: OutgoingMessage, verbosity: DisplayVerbosity): RenderedMessage {
 96→    const meta = content.metadata as { tokensUsed?: number; contextSize?: number; cost?: number } | undefined
 97→    if (!meta?.tokensUsed) return { body: '📊 Usage data unavailable', format: 'plain' }
 98→    const costStr = meta.cost != null ? ` · $${meta.cost.toFixed(2)}` : ''
 99→    if (verbosity === 'medium') {
100→      return { body: `📊 ${formatTokens(meta.tokensUsed)} tokens${costStr}`, format: 'plain' }

