 12→  const icons: Record<string, string> = {
 13→    agent: '🤖', logging: '📝', tunnel: '🔗',
 14→    security: '🔒', workspace: '📁', storage: '💾', speech: '🎤',
 15→  }
 16→  const icon = icons[field.group] ?? '⚙️'
 17→
 18→  if (field.type === 'toggle') {
 19→    return `${icon} ${field.displayName}: ${value ? 'ON' : 'OFF'}`
 20→  }
 21→  const displayValue = value === null || value === undefined ? 'Not set' : String(value)
 22→  return `${icon} ${field.displayName}: ${displayValue}`
 23→}
 24→
 25→const SETTINGS_PAGE_SIZE = 4 // 4 field rows + 1 navigation row = 5 max
 26→
 27→function buildSettingsRows(adapter: DiscordAdapter, page = 0): ActionRowBuilder<ButtonBuilder>[] {
 28→  const config = adapter.core.configManager.get()
 29→  const fields = getSafeFields()
 30→  const totalPages = Math.ceil(fields.length / SETTINGS_PAGE_SIZE)
 31→  const start = page * SETTINGS_PAGE_SIZE
 32→  const pageFields = fields.slice(start, start + SETTINGS_PAGE_SIZE)
 33→
 34→  const rows: ActionRowBuilder<ButtonBuilder>[] = []
 35→
 36→  for (const field of pageFields) {
 37→    const value = getConfigValue(config, field.path)
 38→    const label = formatFieldLabel(field, value)
 39→
 40→    let customId: string
 41→    if (field.type === 'toggle') {
 42→      customId = `s:toggle:${field.path}`
 43→    } else if (field.type === 'select') {
 44→      customId = `s:select:${field.path}`
 45→    } else {
 46→      customId = `s:input:${field.path}`
 47→    }
 48→
 49→    rows.push(
 50→      new ActionRowBuilder<ButtonBuilder>().addComponents(
 51→        new ButtonBuilder()
 52→          .setCustomId(customId)
 53→          .setLabel(label.slice(0, 80))
 54→          .setStyle(ButtonStyle.Secondary),
 55→      ),
 56→    )
 57→  }
 58→
 59→  // Navigation row (if more than 1 page)
 60→  if (totalPages > 1) {
 61→    const navRow = new ActionRowBuilder<ButtonBuilder>()
 62→    if (page > 0) {
 63→      navRow.addComponents(
 64→        new ButtonBuilder()
 65→          .setCustomId(`s:page:${page - 1}`)
 66→          .setLabel('◀️ Previous')
 67→          .setStyle(ButtonStyle.Primary),
 68→      )
 69→    }
 70→    navRow.addComponents(
 71→      new ButtonBuilder()
 72→        .setCustomId('s:pageinfo')
 73→        .setLabel(`Page ${page + 1}/${totalPages}`)
 74→        .setStyle(ButtonStyle.Secondary)
 75→        .setDisabled(true),
 76→    )
 77→    if (page < totalPages - 1) {
 78→      navRow.addComponents(
 79→        new ButtonBuilder()
 80→          .setCustomId(`s:page:${page + 1}`)
 81→          .setLabel('Next ▶️')
 82→          .setStyle(ButtonStyle.Primary),
 83→      )
 84→    }
 85→    rows.push(navRow)
 86→  }
 87→
 88→  return rows
 89→}
