116→export async function handleSettingsButton(
117→  interaction: ButtonInteraction,
118→  adapter: DiscordAdapter,
119→): Promise<void> {
120→  const { customId } = interaction
121→
122→  try {
123→    // Toggle buttons
124→    if (customId.startsWith('s:toggle:')) {
125→      const fieldPath = customId.replace('s:toggle:', '')
126→      const config = adapter.core.configManager.get()
127→      const currentValue = getConfigValue(config, fieldPath)
128→      const newValue = !currentValue
129→
130→      const updates = buildNestedUpdate(fieldPath, newValue)
131→      await adapter.core.configManager.save(updates, fieldPath)
132→
133→      const toast = isHotReloadable(fieldPath)
134→        ? `✅ ${fieldPath} = ${newValue}`
135→        : `✅ ${fieldPath} = ${newValue} (restart needed)`
136→
137→      try {
138→        await interaction.update({
139→          content: '**⚙️ Settings**\nTap to change:',
140→          components: buildSettingsRows(adapter),
141→        })
142→      } catch { /* ignore */ }
143→
144→      try { await interaction.followUp({ content: toast, ephemeral: true }) } catch { /* ignore */ }
145→      return
146→    }
147→
148→    // Select buttons — show options
149→    if (customId.startsWith('s:select:')) {
150→      const fieldPath = customId.replace('s:select:', '')
151→      const config = adapter.core.configManager.get()
152→      const fieldDef = getSafeFields().find((f) => f.path === fieldPath)
153→      if (!fieldDef) return
154→
155→      const options = resolveOptions(fieldDef, config) ?? []
156→      const currentValue = getConfigValue(config, fieldPath)
157→
158→      const rows: ActionRowBuilder<ButtonBuilder>[] = []
159→      let currentRow = new ActionRowBuilder<ButtonBuilder>()
160→      let count = 0
161→
162→      for (const opt of options) {
163→        const marker = opt === String(currentValue) ? ' ✓' : ''
164→        currentRow.addComponents(
165→          new ButtonBuilder()
166→            .setCustomId(`s:pick:${fieldPath}:${opt}`)
167→            .setLabel(`${opt}${marker}`.slice(0, 80))
168→            .setStyle(opt === String(currentValue) ? ButtonStyle.Success : ButtonStyle.Secondary),
169→        )
170→        count++
171→        if (count % 3 === 0) {
172→          rows.push(currentRow)
173→          currentRow = new ActionRowBuilder<ButtonBuilder>()
174→        }
175→      }
176→
177→      if (currentRow.components.length > 0) {
178→        rows.push(currentRow)
179→      }
180→
181→      // Add back button
182→      const backRow = new ActionRowBuilder<ButtonBuilder>().addComponents(
183→        new ButtonBuilder()
184→          .setCustomId('s:back')
185→          .setLabel('◀️ Back')
186→          .setStyle(ButtonStyle.Primary),
187→      )
188→      rows.push(backRow)
189→
190→      try {
191→        await interaction.update({
192→          content: `**⚙️ ${fieldDef.displayName}**\nSelect a value:`,
193→          components: rows.slice(0, 5),
194→        })
195→      } catch { /* ignore */ }
196→      return
197→    }
198→
199→    // Pick buttons — apply selected value
200→    if (customId.startsWith('s:pick:')) {
201→      const parts = customId.replace('s:pick:', '').split(':')
202→      const fieldPath = parts.slice(0, -1).join(':')
203→      const newValue = parts[parts.length - 1]
204→
205→      // For speech.stt.provider: check if API key is configured
206→      if (fieldPath === 'speech.stt.provider') {
207→        const config = adapter.core.configManager.get()
208→        const providerConfig = config.speech?.stt?.providers?.[newValue]
209→        if (!providerConfig?.apiKey) {
210→          // No API key — delegate to assistant
211→          const assistantSessionId = adapter.getAssistantSessionId()
212→          if (assistantSessionId) {
213→            const assistantSession = adapter.core.sessionManager.getSession(assistantSessionId)
214→            if (assistantSession) {
215→              const prompt = `User wants to enable ${newValue} as Speech-to-Text provider, but no API key is configured yet. Guide them to get a ${newValue} API key and set it up. After they provide the key, run both commands: \`openacp config set speech.stt.providers.${newValue}.apiKey <key>\` and \`openacp config set speech.stt.provider ${newValue}\``
216→              await assistantSession.enqueuePrompt(prompt)
217→
218→              try {
219→                await interaction.update({
220→                  content: '**⚙️ Settings**\nTap to change:',
221→                  components: buildSettingsRows(adapter),
222→                })
223→              } catch { /* ignore */ }
224→              try { await interaction.followUp({ content: '🔑 API key needed — check the Assistant thread.', ephemeral: true }) } catch { /* ignore */ }
225→              return
226→            }
227→          }
228→
229→          // No assistant — just warn
230→          try {
231→            await interaction.update({
232→              content: '**⚙️ Settings**\nTap to change:',
233→              components: buildSettingsRows(adapter),
234→            })
235→          } catch { /* ignore */ }
236→          try { await interaction.followUp({ content: `⚠️ Set API key first: \`openacp config set speech.stt.providers.${newValue}.apiKey <key>\``, ephemeral: true }) } catch { /* ignore */ }
237→          return
238→        }
239→      }
240→
241→      const updates = buildNestedUpdate(fieldPath, newValue)
242→      await adapter.core.configManager.save(updates, fieldPath)
243→
244→      try {
245→        await interaction.update({
246→          content: '**⚙️ Settings**\nTap to change:',
247→          components: buildSettingsRows(adapter),
248→        })
249→      } catch { /* ignore */ }
250→      try { await interaction.followUp({ content: `✅ ${fieldPath} = ${newValue}`, ephemeral: true }) } catch { /* ignore */ }
251→      return
252→    }
253→
254→    // Input buttons — delegate to assistant
255→    if (customId.startsWith('s:input:')) {
256→      const fieldPath = customId.replace('s:input:', '')
257→      const config = adapter.core.configManager.get()
258→      const fieldDef = getSafeFields().find((f) => f.path === fieldPath)
259→      if (!fieldDef) return
260→
261→      const currentValue = getConfigValue(config, fieldPath)
262→      const assistantSessionId = adapter.getAssistantSessionId()
263→
264→      if (!assistantSessionId) {
265→        try { await interaction.reply({ content: '⚠️ Assistant is not available.', ephemeral: true }) } catch { /* ignore */ }
266→        return
267→      }
268→
269→      const assistantSession = adapter.core.sessionManager.getSession(assistantSessionId)
270→      if (!assistantSession) {
271→        try { await interaction.reply({ content: '⚠️ Assistant session not found.', ephemeral: true }) } catch { /* ignore */ }
272→        return
273→      }
274→
275→      try { await interaction.deferUpdate() } catch { /* ignore */ }
276→
277→      const prompt = `User wants to change ${fieldDef.displayName} (config path: ${fieldPath}). Current value: ${JSON.stringify(currentValue)}. Ask them for the new value and apply it using: openacp config set ${fieldPath} <value>`
278→      await assistantSession.enqueuePrompt(prompt)
279→
280→      try { await interaction.followUp({ content: `Delegating to assistant — check the Assistant thread.`, ephemeral: true }) } catch { /* ignore */ }
281→      return
282→    }
283→
284→    // Page navigation
285→    if (customId.startsWith('s:page:')) {
286→      const page = parseInt(customId.replace('s:page:', ''), 10)
287→      try {
288→        await interaction.update({
289→          content: '**⚙️ Settings**\nTap to change:',
290→          components: buildSettingsRows(adapter, page),
291→        })
292→      } catch { /* ignore */ }
293→      return
294→    }
295→
296→    // Back button — return to page 0
297→    if (customId === 's:back') {
298→      try {
299→        await interaction.update({
300→          content: '**⚙️ Settings**\nTap to change:',
301→          components: buildSettingsRows(adapter),
302→        })
303→      } catch { /* ignore */ }
304→      return
305→    }
306→
307→    log.warn({ customId }, '[discord-settings] Unhandled settings button')
308→  } catch (err) {
309→    log.error({ err, customId }, '[discord-settings] Settings button handler failed')
310→    try {
311→      if (!interaction.replied && !interaction.deferred) {
312→        await interaction.reply({ content: '❌ Settings action failed.', ephemeral: true })
313→      } else {
314→        await interaction.followUp({ content: '❌ Settings action failed.', ephemeral: true })
315→      }
316→    } catch { /* ignore */ }
317→  }
318→}
319→
320→function buildNestedUpdate(dotPath: string, value: unknown): Record<string, unknown> {
321→  const parts = dotPath.split('.')
322→  const result: Record<string, unknown> = {}
323→  let target = result
324→  for (let i = 0; i < parts.length - 1; i++) {
325→    target[parts[i]] = {}
326→    target = target[parts[i]] as Record<string, unknown>
327→  }
328→  target[parts[parts.length - 1]] = value
329→  return result
330→}
