 12→// In-memory store of pending fixes keyed by "guildId:channelId:messageId"
 13→const pendingFixesStore = new Map<string, PendingFix[]>()
 14→
 15→function renderReport(report: DoctorReport): {
 16→  content: string
 17→  components: ActionRowBuilder<ButtonBuilder>[]
 18→} {
 19→  const icons = { pass: '✅', warn: '⚠️', fail: '❌' }
 20→  const lines: string[] = ['🩺 **OpenACP Doctor**\n']
 21→
 22→  for (const category of report.categories) {
 23→    lines.push(`**${category.name}**`)
 24→    for (const result of category.results) {
 25→      lines.push(`  ${icons[result.status]} ${result.message}`)
 26→    }
 27→    lines.push('')
 28→  }
 29→
 30→  const { passed, warnings, failed, fixed } = report.summary
 31→  const fixedStr = fixed > 0 ? `, ${fixed} fixed` : ''
 32→  lines.push(`**Result:** ${passed} passed, ${warnings} warnings, ${failed} failed${fixedStr}`)
 33→
 34→  const components: ActionRowBuilder<ButtonBuilder>[] = []
 35→
 36→  if (report.pendingFixes.length > 0) {
 37→    const row = new ActionRowBuilder<ButtonBuilder>()
 38→    for (let i = 0; i < Math.min(report.pendingFixes.length, 5); i++) {
 39→      row.addComponents(
 40→        new ButtonBuilder()
 41→          .setCustomId(`m:doctor:fix:${i}`)
 42→          .setLabel(`🔧 Fix: ${report.pendingFixes[i].message.slice(0, 30)}`)
 43→          .setStyle(ButtonStyle.Primary),
 44→      )
 45→    }
 46→    components.push(row)
 47→  }
 48→
 49→  return { content: lines.join('\n'), components }
 50→}
