 52→export async function handleDoctor(
 53→  interaction: ChatInputCommandInteraction,
 54→  _adapter: DiscordAdapter,
 55→): Promise<void> {
 56→  await interaction.deferReply({ ephemeral: true })
 57→
 58→  try {
 59→    const engine = new DoctorEngine()
 60→    const report = await engine.runAll()
 61→    const { content, components } = renderReport(report)
 62→
 63→    // Store pending fixes for button callbacks
 64→    const storeKey = `${interaction.guildId}:${interaction.channelId}`
 65→    if (report.pendingFixes.length > 0) {
 66→      pendingFixesStore.set(storeKey, report.pendingFixes)
 67→    }
 68→
 69→    await interaction.editReply({ content, components })
 70→  } catch (err) {
 71→    log.error({ err }, '[discord-doctor] Doctor command failed')
 72→    await interaction.editReply(
 73→      `❌ Doctor failed: ${err instanceof Error ? err.message : String(err)}`,
 74→    )
 75→  }
 76→}
