102→export async function handleDoctorButton(
103→  interaction: ButtonInteraction,
104→  _adapter: DiscordAdapter,
105→): Promise<void> {
106→  const { customId } = interaction
107→
108→  if (customId === 'm:doctor') {
109→    try { await interaction.deferUpdate() } catch { /* ignore */ }
110→    await runDoctorInline(interaction, _adapter)
111→    return
112→  }
113→
114→  if (customId.startsWith('m:doctor:fix:')) {
115→    const index = parseInt(customId.replace('m:doctor:fix:', ''), 10)
116→    const storeKey = `${interaction.guildId}:${interaction.channelId}`
117→    const fixes = pendingFixesStore.get(storeKey)
118→
119→    try { await interaction.deferUpdate() } catch { /* ignore */ }
120→
121→    if (!fixes || index < 0 || index >= fixes.length) {
122→      try { await interaction.followUp({ content: '⚠️ Fix no longer available.', ephemeral: true }) } catch { /* */ }
123→      return
124→    }
125→
126→    const pending = fixes[index]
127→    try {
128→      const result = await pending.fix()
129→      if (result.success) {
130→        // Re-run doctor to show updated status
131→        const engine = new DoctorEngine()
132→        const report = await engine.runAll()
133→        const { content, components } = renderReport(report)
134→
135→        if (report.pendingFixes.length > 0) {
136→          pendingFixesStore.set(storeKey, report.pendingFixes)
137→        } else {
138→          pendingFixesStore.delete(storeKey)
139→        }
140→
141→        try { await interaction.followUp({ content, components, ephemeral: true }) } catch { /* ignore */ }
142→      } else {
143→        try { await interaction.followUp({ content: `❌ Fix failed: ${result.message}`, ephemeral: true }) } catch { /* */ }
144→      }
145→    } catch (err) {
146→      log.error({ err, index }, '[discord-doctor] Doctor fix callback failed')
147→    }
148→  }
149→}
