 134→          this.guild = guild;
 135→
 136→          // Ensure forum + notification channels exist
 137→          const saveConfig = (updates: Record<string, unknown>) =>
 138→            this.core.configManager.save(
 139→              updates as Parameters<typeof this.core.configManager.save>[0],
 140→            );
 141→          const { forumChannel, notificationChannel } = await ensureForums(
 142→            guild,
 143→            {
 144→              forumChannelId: this.discordConfig.forumChannelId,
 145→              notificationChannelId: this.discordConfig.notificationChannelId,
 146→            },
 147→            saveConfig,
 148→          );
 149→          this.forumChannel = forumChannel;
 150→          this.notificationChannel = notificationChannel;
 151→
 152→          // Init managers that need guild/guildId
 153→          this.skillManager = new SkillCommandManager(
 154→            this.sendQueue,
 155→            this.core.sessionManager,
 156→          );
 157→          this.permissionHandler = new PermissionHandler(
 158→            guild.id,
 159→            (sessionId) => this.core.sessionManager.getSession(sessionId),
 160→            (notification) => this.sendNotification(notification),
 161→          );
 162→
 163→          // Register slash commands
 164→          await registerSlashCommands(guild);
 165→
 166→          // Wire interaction + message handlers
 167→          this.setupInteractionHandler();
 168→          this.setupMessageHandler();
 169→
 170→          // Welcome message
 171→          const welcomeMsg = buildWelcomeMessage(this.core);
 172→          try {
 173→            await this.notificationChannel.send(welcomeMsg);
 174→          } catch (err) {
 175→            log.warn(
 176→              { err },
 177→              "[DiscordAdapter] Failed to send welcome message",
 178→            );
 179→          }
 180→
 181→          // Spawn assistant session
 182→          await this.setupAssistant();
 183→
 184→          log.info("[DiscordAdapter] Initialization complete");
 185→          resolve();
 186→        } catch (err) {
 187→          log.error({ err }, "[DiscordAdapter] Initialization failed");
 188→          reject(err);
 189→        }
 190→      });
 191→
 192→      this.client.login(this.discordConfig.botToken).catch(reject);
 193→    });
 194→  }
