 23→function formatViewerLinks(links?: ViewerLinks, filePath?: string): string {
 24→  if (!links) return "";
 25→  const fileName = filePath ? filePath.split("/").pop() || filePath : "";
 26→  let text = "\n";
 27→  if (links.file) text += `\n[View ${fileName || "file"}](${links.file})`;
 28→  if (links.diff)
 29→    text += `\n[View diff${fileName ? ` — ${fileName}` : ""}](${links.diff})`;
 30→  return text;
 31→}
