 33→function formatHighDetails(
 34→  rawInput: unknown,
 35→  content: unknown,
 36→  maxLen: number,
 37→): string {
 38→  let text = "";
 39→  if (rawInput) {
 40→    const inputStr =
 41→      typeof rawInput === "string"
 42→        ? rawInput
 43→        : JSON.stringify(rawInput, null, 2);
 44→    if (inputStr && inputStr !== "{}") {
 45→      text += `\n**Input:**\n\`\`\`\n${truncateContent(inputStr, maxLen)}\n\`\`\``;
 46→    }
 47→  }
 48→  const details = stripCodeFences(extractContentText(content));
 49→  if (details) {
 50→    text += `\n**Output:**\n\`\`\`\n${truncateContent(details, maxLen)}\n\`\`\``;
 51→  }
 52→  return text;
 53→}
