 55→export function formatToolCall(
 56→  tool: ToolCallMeta,
 57→  verbosity: DisplayVerbosity = "medium",
 58→): string {
 59→  const si = resolveToolIcon(tool);
 60→  const name = tool.name || "Tool";
 61→  const label =
 62→    verbosity === "low"
 63→      ? formatToolTitle(name, tool.rawInput, tool.displayTitle)
 64→      : formatToolSummary(name, tool.rawInput, tool.displaySummary);
 65→  let text = `${si} **${label}**`;
 66→  // viewer links always shown regardless of verbosity
 67→  text += formatViewerLinks(tool.viewerLinks, tool.viewerFilePath);
 68→  // high only: rawInput + content
 69→  if (verbosity === "high") {
 70→    text += formatHighDetails(tool.rawInput, tool.content, 500);
 71→  }
 72→  return text;
 73→}
