 82→export function formatPlan(
 83→  entries: PlanEntry[],
 84→  verbosity: DisplayVerbosity = "medium",
 85→): string {
 86→  // medium: summary count only
 87→  if (verbosity === "medium") {
 88→    const done = entries.filter((e) => e.status === "completed").length;
 89→    return `📋 **Plan:** ${done}/${entries.length} steps completed`;
 90→  }
 91→  // high: full entries
 92→  const statusIcon: Record<string, string> = {
 93→    pending: "⏳",
 94→    in_progress: "🔄",
 95→    completed: "✅",
 96→  };
 97→  const lines = entries.map(
 98→    (e, i) => `${statusIcon[e.status] || "⬜"} ${i + 1}. ${e.content}`,
 99→  );
100→  return `**Plan:**\n${lines.join("\n")}`;
101→}
