103→export function formatUsage(
104→  usage: { tokensUsed?: number; contextSize?: number; cost?: number },
105→  verbosity: DisplayVerbosity = "medium",
106→): string {
107→  const { tokensUsed, contextSize, cost } = usage;
108→  if (tokensUsed == null) return "📊 Usage data unavailable";
109→
110→  // medium: compact one-line
111→  if (verbosity === "medium") {
112→    const costStr = cost != null ? ` · $${cost.toFixed(2)}` : "";
113→    return `📊 ${formatTokens(tokensUsed)} tokens${costStr}`;
114→  }
115→
116→  // high: full progress bar + cost
117→  if (contextSize == null) return `📊 ${formatTokens(tokensUsed)} tokens`;
118→  const ratio = tokensUsed / contextSize;
119→  const pct = Math.round(ratio * 100);
120→  const bar = progressBar(ratio);
121→  const emoji = pct >= 85 ? "⚠️" : "📊";
122→  let text = `${emoji} ${formatTokens(tokensUsed)} / ${formatTokens(contextSize)} tokens\n${bar} ${pct}%`;
123→  if (cost != null) text += `\n💰 $${cost.toFixed(2)}`;
124→  return text;
125→}
